\set ON_ERROR_STOP on
BEGIN;
INSERT INTO human_identities(identity_id,status,display_name)VALUES('05000000-0000-0000-0000-000000000001','Active','M5 Operator');
INSERT INTO organizations(organization_id,name,status,created_by_identity_id)VALUES('15000000-0000-0000-0000-000000000001','M5 Org A','Active','05000000-0000-0000-0000-000000000001'),('15000000-0000-0000-0000-000000000002','M5 Org B','Active','05000000-0000-0000-0000-000000000001');
INSERT INTO memberships(membership_id,organization_id,identity_id,status,activated_at)VALUES('25000000-0000-0000-0000-000000000001','15000000-0000-0000-0000-000000000001','05000000-0000-0000-0000-000000000001','Active',now());
INSERT INTO worker_deliveries(event_id,consumer_name,organization_id,registration_version,handler_version,retry_policy_version,status)VALUES('55000000-0000-0000-0000-000000000001','consumer-v1','15000000-0000-0000-0000-000000000001',1,'v1','postgres-local-v1','Pending'),('55000000-0000-0000-0000-000000000002','consumer-v1','15000000-0000-0000-0000-000000000002',1,'v1','postgres-local-v1','Pending');
WITH candidate AS(SELECT event_id,consumer_name FROM worker_deliveries WHERE status='Pending'ORDER BY first_eligible_at,event_id FOR UPDATE SKIP LOCKED LIMIT 1)UPDATE worker_deliveries d SET status='Processing',attempt_count=attempt_count+1,claim_version=claim_version+1,locked_by='worker-old',locked_until=transaction_timestamp()-interval'1 second',updated_at=transaction_timestamp()FROM candidate WHERE(d.event_id,d.consumer_name)=(candidate.event_id,candidate.consumer_name);
UPDATE worker_deliveries SET status='RetryPending',claim_version=claim_version+1,locked_by=NULL,locked_until=NULL,next_attempt_at=transaction_timestamp(),last_error_code='LeaseExpired'WHERE status='Processing'AND locked_until<transaction_timestamp()AND locked_by='worker-old'AND claim_version=1;
DO $$BEGIN IF EXISTS(SELECT 1 FROM worker_deliveries WHERE locked_by='worker-old')THEN RAISE EXCEPTION 'expired claim was not fenced';END IF;END$$;
UPDATE worker_deliveries SET status='Processing',attempt_count=attempt_count+1,claim_version=claim_version+1,locked_by='worker-new',locked_until=transaction_timestamp()+interval'30 seconds'WHERE event_id='55000000-0000-0000-0000-000000000001'AND status='RetryPending';
DO $$DECLARE changed integer;BEGIN UPDATE worker_deliveries SET status='Processed',locked_by=NULL,locked_until=NULL,terminal_at=now()WHERE event_id='55000000-0000-0000-0000-000000000001'AND status='Processing'AND locked_by='worker-old'AND claim_version=1;GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>0 THEN RAISE EXCEPTION 'stale worker finalized a newer claim';END IF;END$$;
UPDATE worker_deliveries SET status='Failed',locked_by=NULL,locked_until=NULL,terminal_at=now(),failure_category='PermanentContract',last_error_code='SchemaMismatch'WHERE event_id='55000000-0000-0000-0000-000000000001'AND status='Processing'AND locked_by='worker-new';
INSERT INTO worker_dead_letters(event_id,consumer_name,organization_id,failure_category,bounded_error_code,opened_at)VALUES('55000000-0000-0000-0000-000000000001','consumer-v1','15000000-0000-0000-0000-000000000001','PermanentContract','SchemaMismatch',now());
INSERT INTO worker_replay_requests(replay_request_id,organization_id,event_id,consumer_name,replay_mode,status,requested_by_identity_id,requested_by_membership_id,reason,idempotency_key,requested_at)VALUES('75000000-0000-0000-0000-000000000001','15000000-0000-0000-0000-000000000001','55000000-0000-0000-0000-000000000001','consumer-v1','ValidateOnly','Requested','05000000-0000-0000-0000-000000000001','25000000-0000-0000-0000-000000000001','Validate corrected registration','replay-1',now());
DO $$BEGIN BEGIN INSERT INTO worker_replay_requests(replay_request_id,organization_id,event_id,consumer_name,replay_mode,status,requested_by_identity_id,requested_by_membership_id,reason,idempotency_key,requested_at)VALUES(gen_random_uuid(),'15000000-0000-0000-0000-000000000001','55000000-0000-0000-0000-000000000001','consumer-v1','ValidateOnly','Requested','05000000-0000-0000-0000-000000000001','25000000-0000-0000-0000-000000000001','duplicate','replay-1',now());RAISE EXCEPTION 'duplicate replay accepted';EXCEPTION WHEN unique_violation THEN NULL;END;END$$;
ROLLBACK;
